def calculate_simple_gpa(university, student_id):
    '''
    Create a function called calculate_simple_gpa that takes a University object and student_id. 
    For each enrollment from university.get_student_enrollments(student_id), get the course 
    using university.get_course(enrollment.course_code), multiply enrollment.get_grade_points() 
    by course.credits, sum all points and credits, return total_points / total_credits as GPA (0.0-4.0).
    '''
