        else:
            avg_rating = 0.0
        return {'titles': titles, 'count': count, 'avg_rating': avg_rating}
    elif version == 'v3':
        return {
            '@context': 'http://schema.org',
            '@type': 'BookCollection',
            'numberOfItems': len(matches)
        }
    else:
        # Default/fallback, same as v1
        return [row['title'] for row in matches]

